const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const seattle = ee.Geometry.Point([-122.3321, 47.6062]).buffer(50000); // 50km buffer around Seattle
  const years = [2019, 2020, 2021];

  // 2. Data Acquisition & Processing
  let results = {};

  for (const year of years) {
    const startDate = ee.Date.fromYMD(year, 8, 1); // September (0-indexed)
    const endDate = ee.Date.fromYMD(year, 11, 30); // November 30

    const collection = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterBounds(seattle)
      .filterDate(startDate, endDate)
      .select('precipitation');

    const count = collection.size();
    const countInfo = count.getInfo();

    if (countInfo === 0) {
      console.log(`${year} Images: 0`);
      results[year] = null;
      continue;
    }

    // Calculate total rainfall
    const totalRainfall = collection.sum();

    // Get statistics
    const stats = totalRainfall.reduceRegion({
      reducer: ee.Reducer.sum().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: seattle,
      scale: 5000,
      maxPixels: 1e9
    });

    const rainfall = stats.get('precipitation_sum');
    const pixelCount = stats.get('precipitation_count');

    const rainfallInfo = rainfall.getInfo();
    const pixelCountInfo = pixelCount.getInfo();

    console.log(`${year} Images: ${countInfo} (Pixels: ${pixelCountInfo}, Rainfall: ${rainfallInfo ? rainfallInfo.toFixed(1) : 'null'})`);

    if (pixelCountInfo === 0) {
      results[year] = null;
    } else {
      results[year] = rainfallInfo;
    }
  }

  // 3. Validation & Final Answer
  if (results[2019] === null || results[2020] === null || results[2021] === null) {
    if (results[2019] === null && results[2020] === null && results[2021] === null) {
      console.log("<answer>C1</answer>");
    } else {
      console.log("<answer>C2</answer>");
    }
    return;
  }

  if (results[2019] === undefined || results[2020] === undefined || results[2021] === undefined ||
      isNaN(results[2019]) || isNaN(results[2020]) || isNaN(results[2021])) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Check if 2021 rainfall > 2020 AND 2021 > 2019
  const comparison = results[2021] > results[2020] && results[2021] > results[2019];

  console.log(`2019 Total: ${results[2019].toFixed(1)} mm`);
  console.log(`2020 Total: ${results[2020].toFixed(1)} mm`);
  console.log(`2021 Total: ${results[2021].toFixed(1)} mm`);
  console.log(`2021 > 2020: ${results[2021] > results[2020]}`);
  console.log(`2021 > 2019: ${results[2021] > results[2019]}`);

  if (comparison) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
